// Vista → módulo que la habilita. Sirve para ocultarla de la nav y bloquear su acceso si el módulo está apagado (para LEA: inerte, todo ON).
const VIEW_MODULO = { horas:'horas', repricing:'horas', sales:'finanzas', billing:'finanzas', cobranza:'finanzas', conciliacion:'finanzas', anticipos:'finanzas', presupuestoOficina:'finanzas', expenses:'gastos', cajachica:'gastos', cartera:'proyectos', inteligencia:'bi', bi:'bi', portal:'portal' }
// Movilización: el medio va en subcategory (control de Uber) y la glosa se arma "Movilización Desde–Hasta para motivo".
const MEDIOS_MOV = ['Uber','Cabify','DiDi','Taxi','Carga BIP','Estacionamiento','Bencina / peaje']
// Solo los traslados por app/taxi son excepcionales y exigen trayecto y motivo; la carga BIP (transporte público) no pide más.
const MEDIO_CON_DETALLE = new Set(['Uber','Cabify','DiDi','Taxi'])
const medioMovDe = t => { const n=String(t||'').toLowerCase(); return /\buber\b/.test(n)?'Uber':/cabify/.test(n)?'Cabify':/\bdidi\b/.test(n)?'DiDi':/taxi/.test(n)?'Taxi':/metro|\bbip\b|\bbus\b|micro|transporte p/.test(n)?'Carga BIP':/bencina|peaje|\btag\b/.test(n)?'Bencina / peaje':/estacionamiento/.test(n)?'Estacionamiento':'' }
const glosaMovilizacion = (desde,hasta,motivo) => { const m=String(motivo||'').trim().replace(/^para\s+/i,''); return `Movilización ${String(desde||'').trim()}–${String(hasta||'').trim()}${m?` para ${m}`:''}` }
// Fecha breve '15 jun' (omite el año si es el actual; muestra '15 jun 24' si es otro año). Para botones-calendario compactos.
const fechaBreve = d => { if(!d) return ''; const p=String(d).slice(0,10).split('-'); if(p.length!==3) return String(d); const M=['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic']; const cur=new Date().getFullYear(); return `${+p[2]} ${M[+p[1]-1]||p[1]}${+p[0]!==cur?` ${p[0].slice(2)}`:''}` }
// Fecha breve SIEMPRE con año ('19 jun 26'). Para campos donde el año importa.
const fechaConAnio = d => { if(!d) return ''; const p=String(d).slice(0,10).split('-'); if(p.length!==3) return String(d); const M=['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic']; return `${+p[2]} ${M[+p[1]-1]||p[1]} ${p[0].slice(2)}` }
// ¿Marcar esta factura como pagada quedaría SIN respaldo bancario? True SOLO en discrepancia real:
// la cartola YA cubre esa fecha de pago pero ningún movimiento del banco la respalda. (Pago reciente = pendiente cartola → NO avisa; histórico → NO avisa; ya conciliada → NO avisa.)
function sinRespaldoAlPagar(b, fechaPago, respaldoMap={}, cartolaHasta=null){
  if(!b || (b.billing_type||'')==='reembolso') return false
  const monto=b.amount||0, aplicado=respaldoMap[b.id]||0
  const fp=String(fechaPago||'').slice(0,10)
  if(!(monto>0) || aplicado>=monto) return false          // ya conciliada (total)
  if(fp && fp<RESPALDO_CUTOFF) return false                // histórica (sin banco esperado)
  if(!cartolaHasta || !fp || fp>cartolaHasta) return false // pago reciente / sin datos de cartola = pendiente cartola
  return true                                              // cartola cubre la fecha y no hay respaldo → discrepancia real
}
// RUT: normalizador ÚNICO de toda la app = el de cartola (crNormRut): mayúscula, solo dígitos + K (sin puntos, espacios ni guion).
// Antes esta copia conservaba el guion y usaba minúscula (outlier): fallaba dedupe/match entre "12345678-9" y "123456789".
const normRut = crNormRut
// Compareciente vacío o de relleno ("N/A", "S/N", "-"): no identifica a nadie → no se propaga ni se aprende como alias.
const sinNombreReal = s => !String(s||'').replace(/^\s*(n\/?a\.?|s\/?n|sin (nombre|datos)|-+)\s*$/i,'').trim()
// ── MOTOR DE CONCILIACIÓN (determinista, read-only) ─────────────────────────────────────────────────
// Detecta cuotas Programadas ya SALDADAS (fantasma). PURO — no muta nada. Auto-marca SOLO señales
// INEQUÍVOCAS (análisis, no intuición) — cada emitida cubre UNA sola programada (pool con consumo):
//   1 · MISMO PERÍODO por glosa: cuota y emitida declaran el MISMO mes ("Mensual Mayo" ↔ "mayo 26").
//       Nunca marca un mes realmente saltado (Eugenia julio, BM septiembre). alta.
//   2 · MISMA CUOTA N/M etiquetada: la programada "Cuota k/M" y una emitida "Cuota k/M" (mismo M) → el
//       calendario re-generó una cuota ya emitida. alta.
//   3 · COBERTURA por anticipo consolidado (Agustín: 3 adelantos → 1 factura). alta.
// GUARDARRAÍL DEL PLAN (cobro_config): una venta NUNCA puede tener más fantasmas que (filas vivas − nº de
// cuotas del plan). Si el conteo no lo permite, no se marca — esto solo habría evitado los 3 sub-facturados
// (Luis c2, Del Sante oct, JPM sep) que causó la vieja señal de "mismo vencimiento" (ELIMINADA por frágil:
// una emitida genérica "Honorarios" de una cuota vecina la engañaba). Lo que la deriva de fechas deja
// ambiguo se queda PENDIENTE — jamás se esconde una cuota real; se retira a mano o con futura alineación.
function conciliarVentasSaldadas(billing=[], sales=[], anticipos=[], conciliacion=[], ufMap={}, fantasmaNo=new Set()){
  const act=(billing||[]).filter(b=>!b.deleted_at && b.status!=='Anulada' && (b.billing_type||'')!=='reembolso')
  const saleById={}; (sales||[]).forEach(s=>{ saleById[String(s.id)]=s })
  const bankFacturaIds=new Set((conciliacion||[]).filter(c=>c.tipo_destino==='factura'&&c.factura_id).map(c=>String(c.factura_id)))
  const bySale={}; act.forEach(b=>{ if(b.sale_id) (bySale[String(b.sale_id)]=bySale[String(b.sale_id)]||[]).push(b) })
  const amtOf=b=>montoFactura(b)||b.amount||0
  const close=(a,b)=>{ const x=amtOf(a),y=amtOf(b); if(!x||!y) return false; return Math.abs(x-y)/Math.max(x,y) < 0.03 }
  const out=[]
  Object.entries(bySale).forEach(([sid,rows])=>{
    const sale=saleById[sid]||null
    const emitidas=rows.filter(b=>b.invoice_no && b.status!=='Programada')
    const progs=rows.filter(b=>b.status==='Programada').sort((a,b)=>String(a.due||'').localeCompare(String(b.due||'')))
    if(!progs.length || !emitidas.length) return
    const emitIds=new Set(emitidas.map(e=>String(e.id)))
    const antIntoEmit=(anticipos||[]).filter(a=>a.estado==='consumido'&&String(a.sale_id||'')===sid&&a.billing_id&&emitIds.has(String(a.billing_id)))
    const pool=emitidas.map(e=>({e, per:concPeriodoOf(e.concept), cn:cuotaNMof(e.concept), used:false}))
    const take=pred=>{ const c=pool.find(x=>!x.used&&pred(x)); if(c){ c.used=true; return c.e } return null }
    const matched=[]; const rest=[]
    progs.forEach(p=>{
      if(fantasmaNo.has(String(p.id))) return   // "es pendiente, no fantasma" → aprendido, nunca re-marcar
      const pPer=concPeriodoOf(p.concept), pCn=cuotaNMof(p.concept)
      let hit=null, via=null
      if(pPer){ hit=take(x=>x.per===pPer && close(x.e,p)); if(hit) via='periodo' }               // 1 · mismo mes en la glosa
      if(!hit && pCn){ hit=take(x=>x.cn && x.cn.n===pCn.n && x.cn.tot===pCn.tot); if(hit) via='cuota' }  // 2 · misma Cuota k/M
      if(hit) matched.push({prog:p, hit, via}); else rest.push(p)
    })
    // 3 · cobertura por anticipo consolidado (una factura respaldada por adelantos cubre lo que resta)
    if(rest.length && antIntoEmit.length){
      const restSum=rest.reduce((s,r)=>s+(amtOf(r)||0),0)
      const big=pool.find(x=>!x.used && antIntoEmit.some(a=>String(a.billing_id)===String(x.e.id)) && amtOf(x.e) >= restSum*0.97)
      if(big){ big.used=true; rest.forEach(r=>matched.push({prog:r, hit:big.e, via:'cobertura'})); rest.length=0 }
    }
    // GUARDARRAÍL DEL PLAN: nunca marcar más que el excedente real (filas vivas − nº de cuotas del plan).
    const planN=planDeVenta(sale).length
    let cap=matched.length
    if(planN>0){ const excedente=Math.max(0,(emitidas.length+progs.length)-planN); cap=Math.min(cap,excedente) }
    const final=matched.slice(0,cap)   // periodo/cuota/cobertura son inequívocos; el cap solo recorta si el plan no da
    final.forEach(({prog,hit,via})=>{
      const razones=[]
      if(via==='periodo') razones.push(`Ya emitida como N° ${folioN(hit.invoice_no)||hit.invoice_no} — mismo período (${concPeriodoOf(hit.concept)})`)
      else if(via==='cuota') razones.push(`Ya emitida como N° ${folioN(hit.invoice_no)||hit.invoice_no} — misma ${(cuotaNMof(prog.concept)||{}).n}/${(cuotaNMof(prog.concept)||{}).tot}`)
      else if(via==='cobertura') razones.push(`Trato facturado como N° ${folioN(hit.invoice_no)||hit.invoice_no} con anticipos consolidados (${fmt(amtOf(hit))})`)
      if(bankFacturaIds.has(String(hit.id))) razones.push('con pago conciliado en el banco')
      out.push({ prog, sale, monto:amtOf(prog)||prog.amount||0, posterior:hit, razones, conf:'alta', via })
    })
  })
  return out.sort((a,b)=>(b.monto||0)-(a.monto||0))
}

const simNombre = (a,b) => { const x=nrmCliente(a),y=nrmCliente(b); if(!x||!y) return 0; if(x===y) return 1; return 1 - _lev(x,y)/Math.max(x.length,y.length) }
// Clientes EXISTENTES parecidos a un nombre NUEVO (misma regla que el detector) → alarma que BLOQUEA la creación
// para no duplicar (prevención > fusión). Incluye ocasionales (un dup contra un ocasional también importa); excluye interno y la propia ficha.
function clientesParecidos(name, clients=[], excludeId=null){
  const n=_normTxt(name); if(!n) return []
  const toks=n.split(' ').filter(w=>w.length>1)
  const out=[]
  for(const c of (clients||[])){
    if(!c||!c.name||c.deleted_at||c.is_internal||(excludeId!=null&&String(c.id)===String(excludeId))) continue
    const cn=_normTxt(c.name); if(!cn) continue
    const ct=cn.split(' ').filter(w=>w.length>1)
    let tipo=null
    if(cn===n) tipo='exacto'
    else { const short=toks.length<=ct.length?toks:ct, long=toks.length<=ct.length?ct:toks
      if(short.length>=2 && short.every(t=>long.includes(t))) tipo='contenido'
      else if(toks.length===ct.length && Math.min(n.length,cn.length)>=6 && _lev(n,cn)<=2) tipo='typo' }
    if(tipo) out.push({cliente:c, tipo})
  }
  const rank={exacto:0,contenido:1,typo:2}
  out.sort((a,b)=>rank[a.tipo]-rank[b.tipo])
  return out
}
const _tipoDupLbl = t => t==='exacto'?'idéntico':t==='contenido'?'muy similar':'posible typo'
// Motivos de rechazo de una propuesta ("por qué perdimos"): picklist canónico; "Otro" agrega texto libre y se aprende.
const MOTIVOS_RECHAZO = ['Precio / honorarios','Se fue con otro estudio','Lo resolvió internamente','Sin respuesta / se enfrió','Lo postergó (timing)','Fuera de nuestra área','Conflicto de interés']
// Factura con folio del SII: nunca se elimina, se anula con nota de crédito (misma regla que el trigger trg_billing_guard_folio_delete).
const conFolioSII = b => !!String(b?.invoice_no||'').trim()
const MSG_NO_BORRAR_FOLIO = 'Las facturas con folio del SII no se eliminan: se anulan con nota de crédito.'
// Folio SOLO dígitos: para deduplicar facturas sin importar si vienen "318" o "Factura 318" (causa de duplicados en cargas).
const folioDigits = no => String(no||'').replace(/\D/g,'')
// Buscador de cabecera (mismo lenguaje: fondo suave, sin borde, píldora)
const chipSearch = {height:32,width:'100%',background:C.bgSoft,border:'none',borderRadius:20,fontSize:13,padding:'0 14px',color:C.text,outline:'none',boxSizing:'border-box'}
// Ítems que por defecto son INGRESO (restan al costo, ej. subarriendo recupera parte del arriendo).
const OFICINA_INGRESO_ITEMS = new Set(['Subarriendo'])
// Cobrado del mes (fuente única, = EstadoResultadosModal): facturas con paid_at en el mes, netas de anuladas/reembolsos, vía cobradoBill. Comisión del mes = terceros_pagos pagados en el mes. Ambas reusadas por OficinaHub para no divergir.
const ingresosMesBill = (billing, ym) => (billing||[]).filter(b=>b&&!b.deleted_at&&b.status!=='Anulada'&&b.billing_type!=='reembolso'&&String(b.paid_at||'').startsWith(ym)).reduce((a,b)=>a+cobradoBill(b),0)
const comisionMesTerc = (terceros, ym) => (terceros||[]).filter(t=>t&&t.estado==='pagado'&&String(t.pagado_at||'').startsWith(ym)).reduce((a,t)=>a+(Number(t.monto)||0),0)
function contadoraBancoMes(expenses, clients, ym){ return contadoraBancoItems(expenses,clients,ym).reduce((a,e)=>a+(Number(e.amount)||0),0) }
function gastosVariosOfiMes(expenses, clients, ym){ return gastosVariosOfiItems(expenses,clients,ym).reduce((a,e)=>a+(Number(e.amount)||0),0) }
const facturadoSiiPeriodo = (billing, ym) => (billing||[]).filter(b=> b && !b.deleted_at && b.dte_xml && b.invoice_no && b.status!=='Anulada' && b.billing_type==='honorarios' && String(b.issued_at||'').startsWith(ym)).reduce((a,b)=>a+montoFactura(b),0)
// Overhead de oficina por hora (fuente única): costos NO-remuneración/mes ÷ horas del equipo CON costo (Σ metas ×4,33).
function overheadHoraDe(costosOfiRows, metas={}, costoHora={}, ym){
  ym = ym || new Date().toISOString().slice(0,7)
  const eff=r=>(r.desde && ym<String(r.desde).slice(0,7))?(r.monto_prev??r.monto):r.monto
  const overheadMes=(costosOfiRows||[]).filter(r=>!['Remuneraciones','Leyes sociales'].includes(r.categoria)).reduce((a,r)=>a+(r.es_ingreso?-1:1)*(Number(eff(r))||0),0)
  const capMes=Object.keys(metas).filter(n=>Number(costoHora[n])>0).reduce((a,n)=>a+(Number(metas[n])||0),0)*4.33
  return capMes>0 ? overheadMes/capMes : 0
}
const equipoPorEmail = () => { const r={}; Object.entries(EQUIPO_RESPALDO).forEach(([n,e])=>{ r[e]=n }); return {...r, ...(_equipo?.pe||{})} }
// Último registro de una bitácora (activity_log por prefijo) → render(row|null). Para tarjetas-resumen que abren la bitácora completa.
// Toca una vez, al montar, el botón que calza con el selector (p. ej. «Analizar» de la liquidación que llegó por correo).
// Clic automático una sola vez por clave (no por montaje): si el paso falla y el componente se vuelve a montar, no repite el clic en bucle.
const _autoClickHechos = new Set()
function AutoClick({sel, clave}){ useEffect(()=>{ const k=clave||sel; if(_autoClickHechos.has(k)) return; _autoClickHechos.add(k); const b=document.querySelector(sel); if(b) b.click() },[sel,clave]); return null }
function BitacoraUltima({prefijo, render}){
  const [row,setRow]=useState(undefined)
  useEffect(()=>{ let vivo=true; if(DEMO){ setRow((demoData.historial||[]).filter(r=>String(r.action).startsWith(prefijo)).sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)))[0]||null); return }
    supabase.from('activity_log').select('id,action,created_at').like('action',prefijo+'%').order('created_at',{ascending:false}).limit(1)
      .then(({data})=>{ if(vivo) setRow((data||[])[0]||null) }).catch(()=>{ if(vivo) setRow(null) })
    return ()=>{ vivo=false } },[prefijo])
  return render(row)
}

// Bitácora de cargas del SII (sii_import_batches): TODA carga deja registro (XML lo hace vía ensureBatch; PDF/Drive/Excel pasan por aquí). Nunca bloquea.
async function logCargaSII({tipo, n=0, user, period=null, files=[]}){
  if(DEMO) return
  try{ await supabase.from('sii_import_batches').insert({ created_by:user?.name||null, period, docs_total:n, skipped:0, files, counts:n?{cre:n}:{}, tipo }) }catch(_){}
}

// CORTE DE APERTURA: lo anterior al corte se resume en UN movimiento "Saldo de apertura" (category 'Apertura': fondo si queda
